content:
:root {
  --bg: #0b1120;
  --card: #111827;
  --panel: #0f172a;
  --border: #1f2937;
  --text: #e5e7eb;
  --muted: #9ca3af;
  --primary: #3b82f6;
  --success: #16a34a;
  --warn: #d97706;
  --add-bg: rgba(22, 163, 74, 0.18);
  --add-fg: #4ade80;
  --del-bg: rgba(220, 38, 38, 0.20);
  --del-fg: #f87171;
  --hunk-fg: #38bdf8;
}
* { box-sizing: border-box; }

body { margin: 0; font-family: system-ui, -apple-system, sans-serif; background: var(--bg); color: var(--text); }
.topbar { display: flex; justify-content: space-between; align-items: center; padding: 12px 20px; background: var(--card); border-bottom: 1px solid var(--border); gap: 16px; }
.brand { font-weight: 700; font-size: 16px; display: flex; align-items: center; gap: 8px; white-space: nowrap; }
.badge { font-size: 11px; background: #1e3a8a; color: #93c5fd; padding: 2px 8px; border-radius: 999px; }
.badge.goal { background: #374151; color: #f3f4f6; }
.badge.goal.done { background: #14532d; color: #4ade80; }
.badge.goal.active { background: #78350f; color: #fbbf24; }

/* Status LEDs */
.led-cluster { display: inline-flex; align-items: center; gap: 8px; padding: 3px 8px; background: #0f172a; border: 1px solid #334155; border-radius: 999px; }
.led { display: inline-flex; align-items: center; gap: 5px; border: none; padding: 0; background: transparent; cursor: default; }
.led.green { width: 10px; height: 10px; border-radius: 50%; background: #14532d; transition: all 0.2s; }
.led.green.on { background: #22c55e; box-shadow: 0 0 8px #22c55e, 0 0 14px rgba(34, 197, 94, 0.6); }
.led.red .led-dot { width: 10px; height: 10px; border-radius: 50%; background: #450a0a; transition: all 0.2s; }
.led.red.on { cursor: pointer; background: rgba(220, 38, 38, 0.2); border: 1px solid #ef4444; padding: 2px 8px 2px 6px; border-radius: 999px; }
.led.red.on .led-dot { background: #ef4444; box-shadow: 0 0 8px #ef4444, 0 0 14px rgba(239, 68, 68, 0.8); animation: pulseRed 1.2s infinite; }
.led-label { font-size: 11px; font-weight: 700; color: #fecaca; }
@keyframes pulseRed { 0%, 100% { opacity: 1; } 50% { opacity: 0.45; } }
.project-bar { display: flex; gap: 8px; flex: 1; max-width: 620px; }
.layout { display: grid; grid-template-columns: 340px 1fr; gap: 16px; padding: 16px 20px; max-width: 1440px; margin: 0 auto; }
.card { background: var(--card); border: 1px solid var(--border); border-radius: 10px; padding: 14px; display: flex; flex-direction: column; gap: 10px; }
.card-head { display: flex; justify-content: space-between; align-items: center; gap: 8px; }
.card-head h3 { margin: 0; font-size: 14px; font-weight: 600; }
.sidebar { height: calc(100vh - 92px); }
.workspace { display: flex; flex-direction: column; gap: 16px; }
input, textarea, select { background: var(--panel); color: var(--text); border: 1px solid #374151; border-radius: 6px; padding: 8px 10px; font-size: 13px; width: 100%; }
textarea { min-height: 95px; resize: vertical; font-family: inherit; }
textarea.mono { font-family: ui-monospace, Consolas, monospace; font-size: 12px; }
textarea.small { min-height: 80px; }
.num-input { width: 95px; display: inline-block; margin-left: 4px; }
.row { display: flex; gap: 8px; align-items: center; }
.wrap { flex-wrap: wrap; }
.btn { border: none; border-radius: 6px; padding: 8px 12px; font-size: 13px; font-weight: 600; cursor: pointer; color: #fff; white-space: nowrap; }
.btn.primary { background: var(--primary); }
.btn.success { background: var(--success); }
.btn.warn { background: var(--warn); }
.btn.ghost { background: #374151; }
.btn:hover { filter: brightness(1.1); }
.file-list { flex: 1; overflow-y: auto; border: 1px solid var(--border); border-radius: 6px; padding: 6px; background: var(--panel); }
.fitem { display: flex; align-items: center; gap: 8px; padding: 4px 6px; border-radius: 4px; font-size: 12px; font-family: ui-monospace, monospace; cursor: pointer; }
.fitem:hover { background: #1e293b; }
.fitem input { width: auto; }
.fmeta { margin-left: auto; color: var(--muted); font-size: 11px; }
.token-meter { display: flex; justify-content: space-between; font-size: 12px; padding-top: 6px; border-top: 1px solid var(--border); }
.chips { display: flex; flex-wrap: wrap; gap: 6px; }
.chip { display: flex; align-items: center; gap: 6px; background: #1e293b; border: 1px solid #334155; border-radius: 6px; padding: 4px 8px; font-size: 12px; }
.chip select { width: auto; padding: 2px 6px; font-size: 11px; }
.chip input.rng { width: 64px; padding: 2px 6px; font-size: 11px; }
.qa-container { display: flex; flex-direction: column; gap: 10px; }
.qa-card { background: #0f172a; border: 1px solid #3b82f6; border-radius: 8px; padding: 10px 12px; display: flex; flex-direction: column; gap: 6px; }
.qa-title { font-weight: 600; font-size: 13px; color: #93c5fd; }
.qa-opt { display: flex; align-items: center; gap: 8px; font-size: 13px; cursor: pointer; }
.qa-opt input { width: auto; }
.diff-container { display: flex; flex-direction: column; gap: 10px; max-height: 360px; overflow-y: auto; }
.diff-file { border: 1px solid var(--border); border-radius: 6px; overflow: hidden; background: #020617; }
.diff-header { display: flex; justify-content: space-between; padding: 6px 10px; background: #1e293b; font-family: ui-monospace, monospace; font-size: 12px; font-weight: 600; }
.diff-header.ready, .diff-header.applied { color: var(--add-fg); }
.diff-header.error { color: var(--del-fg); }
.diff-body { font-family: ui-monospace, Consolas, monospace; font-size: 12px; line-height: 1.45; overflow-x: auto; }
.dline { padding: 1px 10px; white-space: pre; }
.dline.add { background: var(--add-bg); color: var(--add-fg); }
.dline.del { background: var(--del-bg); color: var(--del-fg); }
.dline.hunk { color: var(--hunk-fg); background: rgba(56, 189, 248, 0.08); }
.dline.meta { color: var(--muted); }
.muted { color: var(--muted); font-size: 12px; }
.chk { display: flex; align-items: center; gap: 6px; font-size: 12px; color: var(--muted); cursor: pointer; }
.chk input { width: auto; }
.modal { position: fixed; inset: 0; background: rgba(0, 0, 0, 0.65); display: flex; align-items: center; justify-content: center; z-index: 50; }
.modal.hidden { display: none; }
.modal-card { background: var(--card); border: 1px solid #334155; border-radius: 10px; padding: 16px; width: min(560px, 92vw); display: flex; flex-direction: column; gap: 10px; }
.hidden { display: none !important; }
.col { display: flex; flex-direction: column; gap: 8px; }

/* Tree explorer */
.tree-folder { display: flex; flex-direction: column; }
.tree-row { display: flex; align-items: center; gap: 6px; padding: 3px 6px; border-radius: 4px; font-size: 12px; font-family: ui-monospace, monospace; cursor: pointer; user-select: none; }
.tree-row:hover { background: #1e293b; }
.tree-row input[type="checkbox"] { width: auto; margin: 0; cursor: pointer; }
.tree-caret { width: 12px; text-align: center; color: var(--muted); font-size: 10px; }
.tree-children { display: flex; flex-direction: column; border-left: 1px dashed #334155; margin-left: 11px; padding-left: 6px; }
.tree-children.collapsed { display: none; }
.tree-folder-lbl { color: #93c5fd; font-weight: 600; }
.tree-file-lbl { color: var(--text); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

/* Collapsible AI Todo Plan */
.plan-panel { border-color: #334155; }
.plan-summary { display: flex; justify-content: space-between; align-items: center; cursor: pointer; font-size: 13px; font-weight: 600; color: #93c5fd; list-style: none; }
.plan-summary::-webkit-details-marker { display: none; }
.plan-summary::before { content: "▸ "; margin-right: 6px; }
details[open] > .plan-summary::before { content: "▾ "; }
.plan-body { display: flex; flex-direction: column; gap: 6px; padding-top: 8px; border-top: 1px solid var(--border); }
.plan-item { display: flex; flex-direction: column; gap: 4px; font-size: 13px; }
.plan-main { display: flex; align-items: center; gap: 8px; font-weight: 500; }
.plan-sublist { display: flex; flex-direction: column; gap: 3px; margin-left: 22px; padding-left: 8px; border-left: 1px solid #334155; font-size: 12px; color: var(--muted); }
.plan-sub { display: flex; align-items: center; gap: 6px; }
.plan-done { text-decoration: line-through; opacity: 0.6; }

/* Code Editor Modal */
.editor-modal-card { width: min(920px, 95vw); height: min(82vh, 760px); }
.editor-wrap { display: flex; flex: 1; min-height: 0; border: 1px solid #334155; border-radius: 6px; background: #020617; overflow: hidden; position: relative; }
.editor-gutter { margin: 0; padding: 10px 8px; background: #0f172a; color: #64748b; font-family: ui-monospace, Consolas, monospace; font-size: 13px; line-height: 1.5; text-align: right; user-select: none; overflow: hidden; min-width: 44px; border-right: 1px solid #1e293b; z-index: 3; }
.editor-textarea { flex: 1; border: none; border-radius: 0; background: #020617; color: #e2e8f0; font-family: ui-monospace, Consolas, monospace; font-size: 13px; line-height: 1.5; padding: 10px 12px; resize: none; tab-size: 4; outline: none; white-space: pre; overflow: auto; box-sizing: border-box; }
.editor-syntax-view { flex: 1; margin: 0; padding: 10px 12px; background: #020617; color: #e2e8f0; font-family: ui-monospace, Consolas, monospace; font-size: 13px; line-height: 1.5; tab-size: 4; white-space: pre; overflow: auto; box-sizing: border-box; }

.syntax-kw { color: #f472b6; font-weight: bold; }
.syntax-str { color: #a5f3fc; }
.syntax-num { color: #fde047; }
.syntax-com { color: #64748b; font-style: italic; }
.syntax-fn { color: #60a5fa; }
.syntax-tag { color: #38bdf8; }
.syntax-attr { color: #c084fc; }

/* Inline Status & Action Popup */
.inline-popup { display: flex; justify-content: space-between; align-items: center; gap: 12px; padding: 12px 16px; border-radius: 10px; border: 1px solid #334155; background: #1e293b; transition: all 0.2s ease; }
.inline-popup-content { display: flex; align-items: center; gap: 12px; }
.popup-icon { font-size: 18px; line-height: 1; }
.inline-popup-text { display: flex; flex-direction: column; gap: 2px; }
.inline-popup-text strong { font-size: 13px; color: var(--text); }
.inline-popup.info { background: rgba(30, 58, 138, 0.28); border-color: #3b82f6; }
.inline-popup.success { background: rgba(20, 83, 45, 0.35); border-color: #16a34a; }
.inline-popup.red { background: rgba(153, 27, 27, 0.42); border-color: #ef4444; box-shadow: 0 0 0 2px rgba(239, 68, 68, 0.22); }
.inline-popup.red strong { color: #fecaca; }
.inline-popup.red .muted { color: #fca5a5; }
.btn.danger { background: #dc2626; color: #fff; }
.btn.danger:hover { background: #b91c1c; }
.choice-option-btn { display: flex; justify-content: space-between; align-items: center; width: 100%; text-align: left; padding: 10px 12px; background: #0f172a; border: 1px solid #334155; border-radius: 6px; color: var(--text); font-size: 13px; cursor: pointer; }
.choice-option-btn:hover { border-color: #3b82f6; background: #1e293b; }

/* Right-click Context Menu */
.context-menu { position: fixed; z-index: 1000; background: #111827; border: 1px solid #334155; border-radius: 8px; padding: 4px; box-shadow: 0 10px 25px rgba(0,0,0,0.5); min-width: 140px; display: flex; flex-direction: column; gap: 2px; }
.ctx-item { padding: 8px 12px; font-size: 12px; color: #e2e8f0; border-radius: 4px; cursor: pointer; display: flex; align-items: center; gap: 8px; }
.ctx-item:hover { background: #1e293b; color: #38bdf8; }
.ctx-item.danger:hover { background: rgba(220, 38, 38, 0.2); color: #f87171; }

@media (max-width: 900px) { .layout { grid-template-columns: 1fr; } .sidebar { height: 320px; } }
